L34_1.m_Pos = "C"
L34_1.m_Talk_KOREA = "하지만, 잠결에 어떤 연주를 들은 것 같사온데..."
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "ですが、夢うつつに何かの演奏が聞こえましたが……"
L34_1.m_Talk_ENG = "But... I feel as though I heard some kind of performance in my sleep..."
