L45_1 = "우리 모두, 수많은 실수와 실패를 되풀이했지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "我々は皆、幾度となく間違いと失敗を繰り返した。"
