L5_1 = "수많은 세계를 집어삼킨 마왕 타기리온의 행보를, 우리가 멈추는 거야."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "数多の世界を飲み込んできた魔王タギリオンの歩みを、我々が止めるのさ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "We will stop the advance of the Demon Lord Thagirion, who has devoured countless worlds."
L4_1.m_Talk_ENG = L5_1
L5_1 = "我們要阻止吞噬無數世界的魔王，塔基里翁的行動。"
