L8_1.m_bCharPinupEasingTime = 0.3
L9_1 = "무슨 꿍꿍인진 몰라도, 클리포트 게임이 끝나지 않았단 건 아직 살아있다는 뜻이겠지?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "どういうつもりかは分からないけど、クリフォトゲームが終わってないってことは、まだ生きてるってことだよね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I don't know what she's planning, but if the Qliphoth Game hasn't ended, that must mean she's still alive, right?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "不管她打什麼主意，逆卡巴拉遊戲還沒結束，就代表她還活著吧？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "I don't know what she's planning, but if the Qliphoth Game hasn't ended, that must mean she's still alive, right?"
