L11_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L12_1 = "내가 가져온 그녀의 무기, 울브즈베인이 황금나무가 있는 방향으로 공명하고 있거든."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "私が持ってきた彼女の武器ウルブズベインが、黄金の木の方に向かって共鳴している。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Wolvesbane, the weapon I brought with me, is resonating in the direction of the Golden Tree."
L11_1.m_Talk_ENG = L12_1
L12_1 = "我把她的武器狼之災禍帶來了，它正朝著黃金樹的方向發出共鳴。"
