L13_1.m_Pos = "R"
L13_1.m_bCharPinup = true
L14_1 = "아마 늑대를 데려간 것은 타기리온 혼자만의 판단이 아닐 것입니다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "おそらくオオカミを連れて行ったのは、タギリオンの独断ではないでしょう。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Most likely, it was not Thagirion's decision alone to take the Wolf."
L13_1.m_Talk_ENG = L14_1
L14_1 = "帶走狼恐怕不只是塔基里翁一個人的判斷。"
