L14_1.m_CharStrID = "MORS_SHADOW_NPC_GUN"
L14_1.m_Pos = "R"
L14_1.m_bCharPinup = true
L15_1 = "파괴가 아닌 공존은... 타기리온이 아닌 아우드라의 의지에 가까우니까요."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "破壊ではなく共存は……タギリオンではなくアウドラの意志に近いものですから。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Coexistence rather than destruction... That is closer to Audra's will than Thagirion's."
L14_1.m_Talk_ENG = L15_1
L15_1 = "因為非破壞的共存，更接近奧德拉的意志。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "Coexistence rather than destruction... That is closer to Audra's will than Thagirion's."
