L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 726
L17_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
