L17_1.m_Pos = "R"
L17_1.m_bCharPinup = true
L18_1 = "아우드라는 마왕이 되지 못한 그녀의 또 다른 인격."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "アウドラは魔王になりえなかった彼女のもう一つの人格。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Audra is her other personality. The one who never became the Demon Lord."
L17_1.m_Talk_ENG = L18_1
L18_1 = "奧德拉是她無法成為魔王的另一個人格。"
