L19_1 = "EP15_ACT4_INTERLUDE19@47#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 726
L18_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
