L18_1.m_Face = "UNIT_HATE"
L18_1.m_CharStrID = "MORS_SHADOW_NPC_GUN"
L18_1.m_Pos = "R"
L18_1.m_bCharPinup = true
L19_1 = "그녀는 세계를 파괴하는 타기리온을 대신해, 이곳 낙원의 존재를 다스리고 있사옵니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "彼女は世界を破壊するタギリオンに代わり、この楽園を治めております。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "In place of Thagirion, who destroys worlds, she governs the existence of the Promised Land."
L18_1.m_Talk_ENG = L19_1
L19_1 = "她代替塔基里翁這個毀滅世界的魔王，統治這座樂園。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "In place of Thagirion, who destroys worlds, she governs the existence of the Promised Land."
