L21_1 = "타기리온의 옥좌인 황금나무를 부수는 게 우리의 목적이니, 결국 그녀와의 충돌도 피할 순 없을 거야."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "タギリオンの玉座である黄金の木を潰すことが私たちの目的だから、結局、彼女との衝突は避けられないだろうね。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Since our goal is to destroy the Golden Tree, Thagirion's throne, a clash with her is ultimately unavoidable."
L20_1.m_Talk_ENG = L21_1
L21_1 = "我們的目標是摧毀塔基里翁的王座黃金樹，因此與她的衝突無可避免。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "Since our goal is to destroy the Golden Tree, Thagirion's throne, a clash with her is ultimately unavoidable."
