L24_1 = "하지만 설명을 들었을 땐, 타기리온처럼 공격적인 성향은 아닌 것 같은데."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "だが説明を聞いた感じだと、タギリオンのように攻撃的なタイプではないようだが。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "But from what you've described, she doesn't seem to be as aggressive as Thagirion."
L23_1.m_Talk_ENG = L24_1
L24_1 = "但從說明來看，她似乎並不像塔基里翁那樣具有攻擊性。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "But from what you've described, she doesn't seem to be as aggressive as Thagirion."
L23_1.m_Talk_DEU = L24_1
