L24_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L25_1 = "두 존재가 서로를 의지하고 있다면, 오히려 우리가 평화로운 쪽을 설득해볼 수 있을지도 모르겠군."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "二つの存在が互いを支え合っているのなら、平和を求める方を説得できるかもしれないな。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "If the two of them depend on each other, perhaps we might be able to persuade the more peaceful one."
L24_1.m_Talk_ENG = L25_1
L25_1 = "若兩者彼此依存，也許我們可以試著說服較為溫和的一方。"
