L25_1.m_Pos = "C"
L26_1 = "그 말씀처럼 아우드라에겐 마왕 타기리온과 다른 면모가 있사오나, 그녀를 설득하는 건 어려울 것입니다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "おっしゃる通り、アウドラには魔王タギリオンとは異なる面がございますが、彼女を説得することは難しいと思われます。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "As you say, Audra does have a different side from the Demon Lord Thagirion, but persuading her will be difficult."
L25_1.m_Talk_ENG = L26_1
L26_1 = "正如您所說，奧德拉雖與塔基里翁不同，但要說服她恐怕很困難。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "As you say, Audra does have a different side from the Demon Lord Thagirion, but persuading her will be difficult."
L25_1.m_Talk_DEU = L26_1
