L26_1.m_Pos = "C"
L27_1 = "그녀는 낙원의 존속을 위해 오랫동안 자신의 죽음을 반복한 만큼, 결코 우유부단한 인물이 아니니까요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "彼女は楽園の存続のために長い間自分の死を繰り返してきました。決して優柔不断な人物ではありません。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "She isn't someone indecisive, having repeated her own death for so long for the sake of preserving the Promised Land."
L26_1.m_Talk_ENG = L27_1
L27_1 = "她長久以來為了維持樂園的存續，不斷重複自身的死亡，因此絕不是優柔寡斷之人。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "She isn't someone indecisive, having repeated her own death for so long for the sake of preserving the Promised Land."
