L29_1 = "그래. 그녀를 만난다 해도 늑대를 순순히 돌려주진 않겠지."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ああ。彼女に会えたとしても、大人しくオオカミを返してはくれないだろう。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Yes. Even if we meet her, she likely won't return the Wolf so easily."
L28_1.m_Talk_ENG = L29_1
L29_1 = "沒錯。就算見到她，她也不會輕易交出狼。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "Yes. Even if we meet her, she likely won't return the Wolf so easily."
