L30_1 = "적어도 그녀가 늑대를 저곳에 가둔 이유를 알 수 있다면... 도움이 될지도 모르겠어."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "せめて彼女がオオカミをあそこに閉じ込めた理由が分かれば……手がかりになるんだが。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "At the very least, if we can learn why she imprisoned the Wolf there... it might help."
L29_1.m_Talk_ENG = L30_1
L30_1 = "但至少若能知道她囚禁狼的理由……說不定會有所幫助。"
