L30_1.m_Pos = "C"
L31_1 = "늑대가 클리포트 게임을 매듭짓는 유일한 열쇠이니, 그 열쇠를 영원히 봉인하려 할 생각일지도 모르지요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "オオカミはクリフォトゲームを終わらせる唯一の鍵です。その鍵を永遠に封印するつもりなのかもしれません。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Since the Wolf is the only key that can conclude the Qliphoth Game, she may be intending to seal that key away forever."
L30_1.m_Talk_ENG = L31_1
L31_1 = "狼是終結逆卡巴拉遊戲的唯一鑰匙，她可能想永遠封印那把鑰匙。"
