L48_1 = "<color=#ffd34c>클리포트 게임이 어느 쪽의 승리로도 끝나지 않는 상황이 오면, 어떤 형태로든 게임을 지속 가능하도록 개변한다.</color>"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "<color=#ffd34c>クリフォトゲームがどちらかの勝利で終わらない状況になった場合、いかなる形になろうとも、ゲームを続けられるべく改変する。</color>"
L47_1.m_Talk_JPN = L48_1
L48_1 = "<color=#ffd34c>If a situation arises in which the Qliphoth Game cannot be concluded with either side's victory, it will be altered in some form to ensure the game can continue.</color>"
L47_1.m_Talk_ENG = L48_1
L48_1 = "<color=#ffd34c>若逆卡巴拉遊戲出現任何一方無法獲勝的情況，她將以某種形式改變遊戲，使其得以繼續。</color>"
L47_1.m_Talk_TWN = L48_1
L48_1 = "<color=#ffd34c>If a situation arises in which the Qliphoth Game cannot be concluded with either side's victory, it will be altered in some form to ensure the game can continue.</color>"
