L4_1.m_Pos = "C"
L5_1 = "타기리온이 먼저 반칙을 한 셈이니, 우리에게 유리하게 작용하지 않겠어?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "先にルールを破ったのはタギリオンなんだし、私たちに有利になるんじゃないの？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Since Thagirion was the one who broke the rules first, wouldn't that work in our favor?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "既然塔基里翁先違反規則，對我們應該是有利的吧？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "Since Thagirion was the one who broke the rules first, wouldn't that work in our favor?"
