L22_1 = "DOC_NPC_15_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "당신이 꿈속에서 본 걸 말한 뒤로, 정확히 8일이 지난 시점이죠."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "あなたが夢で見たことを聞かせてくれた時から、ちょうど8日が経過した時点です。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "It happened exactly eight days after you told us what you saw in your dream."
L21_1.m_Talk_ENG = L22_1
L22_1 = "正是你把夢中見到的東西說出來的第8天。"
