L22_1.m_Face = L23_1
L23_1 = "THAMIEL_NORMAL_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "많은 사람들이 죽었나요? 제가 본 것처럼?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "たくさんの人が死にましたか？　夢と同じように？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Did many people die? Just like I saw?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "有很多人死亡嗎？就像我看到的那樣？"
