L25_1 = "DOC_NPC_15_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "천재지변 앞에 저희가 할 수 있는 일엔 한계가 있습니다. 운명이라고나 할까요. 그걸 저희가 바꾼다는 건 쉽지 않은 일이죠."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "天変地異を前に、できることは限られています。運命といいますか。それを私たちが変えることは簡単ではありません。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "There is only so much we can do in the face of a natural disaster. Call it fate, if you will. It is no easy task for us to change something like that."
L24_1.m_Talk_ENG = L25_1
L25_1 = "我們在天災面前能做的有限，或許只能稱之為命運。我們要改變它並不容易。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "There is only so much we can do in the face of a natural disaster. Call it fate, if you will. It is no easy task for us to change something like that."
L24_1.m_Talk_DEU = L25_1
L25_1 = "There is only so much we can do in the face of a natural disaster. Call it fate, if you will. It is no easy task for us to change something like that."
L24_1.m_Talk_FRA = L25_1
