L26_1 = "경고를... 할 수도 있었을 텐데요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "警告をすることくらい……できたはずですが。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "We could have... warned them."
L25_1.m_Talk_ENG = L26_1
L26_1 = "你們明明可以……發出警告。"
