L28_1 = "EP15_ACT4_INTERLUDE19@88#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 726
L27_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "DOC_NPC_15_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "이틀 전, 우리 3급 연구원이 그 주의 기관을 멋대로 방문해 우리 연구소를 언급하며 대피를 요구했다고 하더군요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "2日前、こちらの3級研究員がかの州の機関を勝手に訪ね、当研究所の名を出しながら避難を要求したようです。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Two days ago, one of our Class 3 researchers visited a government agency in that state without authorization and mentioned our institute while urging them to evacuate."
L27_1.m_Talk_ENG = L28_1
L28_1 = "兩天前，我們一名3級研究員擅自造訪該機構，提及我們研究所並要求民眾避難。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "Two days ago, one of our Class 3 researchers visited a government agency in that state without authorization and mentioned our institute while urging them to evacuate."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Two days ago, one of our Class 3 researchers visited a government agency in that state without authorization and mentioned our institute while urging them to evacuate."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP15_ACT4_INTERLUDE19@89#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 726
L28_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "DOC_NPC_15_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "사태가 벌어진 뒤, 정부는 그들의 무능함을 감추기 위해 발 빠르게 움직였습니다. 경찰 인력을 끌고 우리 연구소에 들이닥쳤죠."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "事態が発生した後、政府はその無能さを悟られないよう迅速に動きました。警察を連れて当研究所に押しかけてきたのです。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "After the incident occurred, the government moved quickly to cover up their own incompetence. They brought police forces and stormed our institute."
L28_1.m_Talk_ENG = L29_1
L29_1 = "事後，政府為了掩蓋自身無能，迅速行動、帶著警方闖入我們研究所。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "After the incident occurred, the government moved quickly to cover up their own incompetence. They brought police forces and stormed our institute."
L28_1.m_Talk_DEU = L29_1
L29_1 = "After the incident occurred, the government moved quickly to cover up their own incompetence. They brought police forces and stormed our institute."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP15_ACT4_INTERLUDE19@90#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 726
L29_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "DOC_NPC_15_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "지금 매스컴에선 우리 연구소가 <color=#ffd34c>인권 유린을 자행하며 초자연적 재앙을 숭배하는 사이비 과학 집단</color>으로 묘사되고 있어요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "今マスコミでは、当研究所を<color=#ffd34c>人権を蹂躙し、超自然的な災害を崇拝する異端科学集団</color>と報道しています。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Right now, the media is portraying our institute as a <color=#ffd34c>pseudo-scientific group that commits human rights abuses and worships supernatural disasters</color>."
L29_1.m_Talk_ENG = L30_1
L30_1 = "如今我們研究所被媒體上描繪成<color=#ffd34c>侵犯人權、崇拜超自然災難的邪教科學組織</color>。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "Right now, the media is portraying our institute as a <color=#ffd34c>pseudo-scientific group that commits human rights abuses and worships supernatural disasters</color>."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Right now, the media is portraying our institute as a <color=#ffd34c>pseudo-scientific group that commits human rights abuses and worships supernatural disasters</color>."
L29_1.m_Talk_FRA = L30_1
