L31_1 = "EP15_ACT4_INTERLUDE19@91#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 726
L30_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_SURPRISE"
L31_1 = "THAMIEL_NORMAL_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "경고를 무시한 것도 모자라, 책임을 덮어 씌우려 한다고요?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "警告を無視した挙句、濡れ衣まで着せようとしているんですか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Are you saying they ignored the warning and are now trying to shift the blame onto us?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "不僅無視警告，還反過來推卸責任？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "Are you saying they ignored the warning and are now trying to shift the blame onto us?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Are you saying they ignored the warning and are now trying to shift the blame onto us?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP15_ACT4_INTERLUDE19@92#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 726
L31_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "THAMIEL_NORMAL_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "하지만 제 꿈은 사실이었잖아요. 우린 그들을 도우려 했을 뿐이고요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ですが、私の夢は現実になったではないですか。私たちは彼らを助けようとしただけなのに。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "But my dream was real. We only tried to help them."
L31_1.m_Talk_ENG = L32_1
L32_1 = "但我的夢確實是事實，我們只是想幫助他們。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "But my dream was real. We only tried to help them."
L31_1.m_Talk_DEU = L32_1
L32_1 = "But my dream was real. We only tried to help them."
L31_1.m_Talk_FRA = L32_1
