L34_1 = "EP15_ACT4_INTERLUDE19@93#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 726
L33_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "DOC_NPC_15_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "전조조차 없는 대재난을 경고하기 위한 근거가 꿈이 되어서는 안 됩니다. 그래서는 누구도 믿음을 주지 않아요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "前兆すらない大災害を警告する根拠が夢であってはなりません。それだけでは誰も信じてくれないのです。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "A dream cannot serve as evidence to warn people about a catastrophe that showed no prior signs. No one would believe that."
L33_1.m_Talk_ENG = L34_1
L34_1 = "沒有任何預兆的重大災難，不能以夢作為警告的依據。那樣沒有人會相信。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "A dream cannot serve as evidence to warn people about a catastrophe that showed no prior signs. No one would believe that."
L33_1.m_Talk_DEU = L34_1
L34_1 = "A dream cannot serve as evidence to warn people about a catastrophe that showed no prior signs. No one would believe that."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP15_ACT4_INTERLUDE19@94#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 726
L34_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "DOC_NPC_15_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "그게 저희가 당신과 함께 있는 이유랍니다, 탐미엘. 당신의 능력을 규명하고 세상에 알릴 준비를 하는 거죠."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "それが私たちがあなたと共にいる理由です、タミエル。あなたの能力を究明し、世に知らせる準備をしているのです。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "That is why we are working with you, Tammiel. We are preparing to verify your abilities and make them known to the world."
L34_1.m_Talk_ENG = L35_1
L35_1 = "這就是我們和你在一起的理由，塔米爾。我們要證明你的能力，並將其公諸於世。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "That is why we are working with you, Tammiel. We are preparing to verify your abilities and make them known to the world."
L34_1.m_Talk_DEU = L35_1
L35_1 = "That is why we are working with you, Tammiel. We are preparing to verify your abilities and make them known to the world."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP15_ACT4_INTERLUDE19@95#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 726
L35_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "DOC_NPC_15_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "지금은 세상 사람들이 당신이 불길한 헛소리가 아닌, 진짜 능력이라고 믿을 수 있도록, 그 근거를 모아야 해요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "今は、あなたの話が不吉な虚言などではなく、本物の能力によるものなのだと世間が信じられるように、根拠を集めねばなりません。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "For now, we must gather evidence so people can believe that what you have is not ominous nonsense, but a real ability."
L35_1.m_Talk_ENG = L36_1
L36_1 = "現在我們必須讓世人相信那不是荒唐的胡言亂語，要收集證據，證明是真實的能力。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "For now, we must gather evidence so people can believe that what you have is not ominous nonsense, but a real ability."
L35_1.m_Talk_DEU = L36_1
L36_1 = "For now, we must gather evidence so people can believe that what you have is not ominous nonsense, but a real ability."
L35_1.m_Talk_FRA = L36_1
