L40_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L41_1 = "...미안하네. 내가 괜히 나서는 바람에 자넬 곤란하게 만들었군."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "……すまない。私が差し出がましい真似をしたせいで、君には迷惑をかけてしまった。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "...I'm sorry. I made things difficult for you by stepping in unnecessarily."
L40_1.m_Talk_ENG = L41_1
L41_1 = "……抱歉。是我多管閒事，讓你陷入困擾。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "...I'm sorry. I made things difficult for you by stepping in unnecessarily."
L40_1.m_Talk_DEU = L41_1
L41_1 = "...I'm sorry. I made things difficult for you by stepping in unnecessarily."
L40_1.m_Talk_FRA = L41_1
