L42_1 = "EP15_ACT4_INTERLUDE19@98#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 726
L41_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L41_1.m_bWaitClick = true
