L42_1 = "UNIT_LAUGH"
L41_1.m_Face = L42_1
L42_1 = "THAMIEL_NORMAL_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "곤란할 리가. 내가 먼저 부탁한 거잖아."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "迷惑も何も、私が頼んだことだから。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "It's not difficult at all. I was the one who asked first."
L41_1.m_Talk_ENG = L42_1
L42_1 = "怎麼會，是我自己先提出的。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "It's not difficult at all. I was the one who asked first."
L41_1.m_Talk_DEU = L42_1
L42_1 = "It's not difficult at all. I was the one who asked first."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP15_ACT4_INTERLUDE19@99#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 726
L42_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "UNIT_IDLE"
L42_1.m_Face = L43_1
L43_1 = "THAMIEL_NORMAL_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "TV에선 사람들이 날 마녀라고 부르던데. 그래 보여?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "TVでは、私のことを魔女と呼んでいたけど。そう見える？"
L42_1.m_Talk_JPN = L43_1
