L44_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L45_1 = "그럴 리가. 그들은 자넬 뭐라고 불러야 할지 모를 뿐이야."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "まさか。彼らは君のことを何と呼べばいいか分からないだけだ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Of course not. They just don't know what to call you."
L44_1.m_Talk_ENG = L45_1
L45_1 = "怎麼會。他們只是還不知道該怎麼稱呼你。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "Of course not. They just don't know what to call you."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Of course not. They just don't know what to call you."
L44_1.m_Talk_FRA = L45_1
