L45_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L46_1 = "도시를 날아다니며 마법을 쓰고 사람을 구하는 소녀를 마녀가 아닌 마법소녀로 부르는 것처럼 말이지."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "都市を飛び回り、魔法で人を救う少女のことを、魔女ではなく魔法少女と呼ぶのと同じようにね。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Just like how a girl who flies over the city, uses magic, and saves people is called a magical girl instead of a witch."
L45_1.m_Talk_ENG = L46_1
L46_1 = "就像在城市中飛翔、施展魔法拯救世人的少女不會被稱為魔女，而是魔法少女一樣。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "Just like how a girl who flies over the city, uses magic, and saves people is called a magical girl instead of a witch."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Just like how a girl who flies over the city, uses magic, and saves people is called a magical girl instead of a witch."
L45_1.m_Talk_FRA = L46_1
