L4_1 = "DOC_NPC_15_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "깊은 수면에 빠질수록 더 먼 미래를 내다본다는 건, 무의식 상태가 당신의 잠재력을 극대화시킨다는 뜻이죠."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "眠りが深くなるほどより遠い未来を見るということは、無意識があなたの潜在能力を極大化するということです。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "The deeper you fall into sleep, the farther into the future you can see. That means your unconscious state maximizes your potential."
L3_1.m_Talk_ENG = L4_1
L4_1 = "越是進入深層睡眠，就越能看見更遙遠的未來，代表無意識狀態能將你的潛能放到最大。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "The deeper you fall into sleep, the farther into the future you can see. That means your unconscious state maximizes your potential."
L3_1.m_Talk_DEU = L4_1
L4_1 = "The deeper you fall into sleep, the farther into the future you can see. That means your unconscious state maximizes your potential."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP15_ACT4_INTERLUDE19@106#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 726
L4_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "DOC_NPC_15_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "그래서 이번엔 그 한계를 시험해볼 예정입니다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "だから今回はその限界を試してみるつもりです。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "So this time, we plan to test your limits."
L4_1.m_Talk_ENG = L5_1
L5_1 = "因此，這次我們要測試極限。"
