L5_1.m_bCharPinup = true
L5_1.m_bCharPinupEasingTime = 0.3
L6_1 = "좋네요. 임사 체험이란 거, 한 번쯤 해보고 싶었어요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "いいですね。臨死体験というのを一度やってみたかったんです。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Sounds good. I have always wanted to try something like a near-death experience at least once."
L5_1.m_Talk_ENG = L6_1
L6_1 = "很好。我也想試一次瀕死體驗。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "Sounds good. I have always wanted to try something like a near-death experience at least once."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Sounds good. I have always wanted to try something like a near-death experience at least once."
L5_1.m_Talk_FRA = L6_1
