L7_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L8_1 = "철저히 준비했다곤 해도 위험도가 높은 실험인 건 변치 않네. 원치 않는다면 지금이라도 말하게나."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "徹底的に準備したとはいえ、危険性の高い実験であることに変わりはない。望まないなら今からでも言いたまえ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Even with all our preparations, it doesn't change the fact that this is a highly dangerous experiment. If you don't want to go through with it, just say the word."
L7_1.m_Talk_ENG = L8_1
L8_1 = "雖然已經做好充分準備，但這依然是高風險實驗。如果你不願意，現在還可以拒絕。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "Even with all our preparations, it doesn't change the fact that this is a highly dangerous experiment. If you don't want to go through with it, just say the word."
