L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "이게... 어떻게 된 거지? 저 괴물들은 대체... 어디서 나타난 거야?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "これは……どういうこと？　あの化け物たちはいったい……どこから現れたの？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "What... happened here? Where did those monsters... come from?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "這是……怎麼回事？那些怪物……是從哪裡來的？"
