L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L26_1 = "자네가 가사 상태에 들어간 동안, 연구단지를 중심으로 동시다발적인 이상 현상이 발생했어."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "君が仮死状態になっている間、研究団地を中心に同時多発的な異常現象が発生したんだ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "While you were in a comatose state, simultaneous abnormal phenomena occurred centered around the research complex."
L25_1.m_Talk_ENG = L26_1
L26_1 = "在你陷入昏迷狀態時，以研究園區為中心，發生了多起異常現象。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "While you were in a comatose state, simultaneous abnormal phenomena occurred centered around the research complex."
L25_1.m_Talk_DEU = L26_1
L26_1 = "While you were in a comatose state, simultaneous abnormal phenomena occurred centered around the research complex."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
