L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "R"
L19_1 = "무사했었구나! 함선에 들어간 뒤로 만나지 못했는데, 이런 곳에 있었던 거야?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "無事だったんだね！　艦船に入ってからは合流できなかったけど、こんなところにいたんだ？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "You're safe! I hadn't seen you since we entered the ship. Were you here all along?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "你還活著！自從進入艦船後就沒再見到你，原來你在這裡啊？"
