L19_1.m_Pos = "L"
L20_1 = "맞아요. 타기리온과 맞닥뜨렸을 땐 죽는단 각오였는데... 정신을 차려보니 한 소녀한테 이곳으로 끌려와버렸죠."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "はい。タギリオンに出くわした時は死を覚悟しましたが……気がついたら、ある少女の手でここに連れてこられていました。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Yes. When I encountered Thagirion, I was prepared to die... but when I came to my senses, a young girl had brought me here."
L19_1.m_Talk_ENG = L20_1
L20_1 = "對。當我與塔基里翁對峙時，本以為必死無疑……醒來時卻被一名少女帶到這裡。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "Yes. When I encountered Thagirion, I was prepared to die... but when I came to my senses, a young girl had brought me here."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Yes. When I encountered Thagirion, I was prepared to die... but when I came to my senses, a young girl had brought me here."
L19_1.m_Talk_FRA = L20_1
