L23_1.m_fTalkTime = 0.03
L24_1 = "あの少女はアウドラです。タギリオンが魔王になる前に残した、彼女の弱い部分です。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "She is Audra. She is the fragile personality that Thagirion left behind before becoming the Demon Lord."
L23_1.m_Talk_ENG = L24_1
L24_1 = "那個少女是奧德拉。是塔基里翁成為魔王前，殘留下來的脆弱人格。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "She is Audra. She is the fragile personality that Thagirion left behind before becoming the Demon Lord."
L23_1.m_Talk_DEU = L24_1
L24_1 = "She is Audra. She is the fragile personality that Thagirion left behind before becoming the Demon Lord."
L23_1.m_Talk_FRA = L24_1
