L24_1.m_Face = "UNIT_SERIOUS"
L24_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L24_1.m_Pos = "L"
L25_1 = "타기리온과 행보는 정반대지만, 결국 둘의 목적은 다르지 않을 테니 함부로 믿어선 안 됩니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "行動はタギリオンと正反対だけど、結局二人の目的は同じはずなので、簡単に信用してはいけません。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Her path is the complete opposite of Thagirion's, but in the end their objective is not different, so you shouldn't trust her carelessly."
L24_1.m_Talk_ENG = L25_1
L25_1 = "雖然行動與塔基里翁相反，但目的未必不同，所以不能輕易相信她。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "Her path is the complete opposite of Thagirion's, but in the end their objective is not different, so you shouldn't trust her carelessly."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Her path is the complete opposite of Thagirion's, but in the end their objective is not different, so you shouldn't trust her carelessly."
