L27_1 = "그래. 날 살려둔 것도, 분명 어떤 속셈이 있어서겠지."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "そうだね。私を生かしておいたのも、きっと何か理由があるんだろうし。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Right. She must've had some ulterior motive for keeping me alive."
L26_1.m_Talk_ENG = L27_1
L27_1 = "沒錯。她救我，也一定另有目的。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "Right. She must've had some ulterior motive for keeping me alive."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Right. She must've had some ulterior motive for keeping me alive."
