L33_1.m_bCharPinupEasingTime = 0.3
L34_1 = "낙원의 벨레스란 사제가 그녀의 기억을 지우려 했어. 지금의 어려진 모습은 그때 힘을 잃은 영향이야."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "楽園のヴェレスという司祭が彼女の記憶を消そうとしたんです。その時力を失ったせいで、今は幼い姿になっています。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "A priest named Veles of the Promised Land tried to erase her memories. Her current younger appearance is the result of losing her power at that time."
L33_1.m_Talk_ENG = L34_1
L34_1 = "樂園的貝雷斯曾試圖抹去她的記憶。現在這副年幼的樣子，也是因此失去力量的影響。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "A priest named Veles of the Promised Land tried to erase her memories. Her current younger appearance is the result of losing her power at that time."
L33_1.m_Talk_DEU = L34_1
