L34_1.m_Pos = "R"
L34_1.m_bCharPinup = true
L35_1 = "그 벨레스란 작자가 당신의 아버지라고?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "そのヴェレスって人があなたの父親なの？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "That Veles guy is your father?"
