L36_1 = "EP15_ACT4_INTERLUDE19@161#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 235
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 726
L35_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_DESPAIR"
L35_1.m_CharStrID = "MORS_SHADOW_NPC_GUN"
L35_1.m_Pos = "C"
L36_1 = "지금은 타기리온과 낙원을 이끌며 수많은 세계를 희생시킨 악인일 뿐이옵니다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "今の彼はタギリオンと楽園を率いて数多くの世界を犠牲にした悪人に過ぎません。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Now he's nothing more than a villain who leads the Promised Land together with Thagirion and sacrifices countless worlds."
L35_1.m_Talk_ENG = L36_1
L36_1 = "如今，他只是與塔基里翁一同支配樂園、犧牲無數世界的惡人。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "Now he's nothing more than a villain who leads the Promised Land together with Thagirion and sacrifices countless worlds."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Now he's nothing more than a villain who leads the Promised Land together with Thagirion and sacrifices countless worlds."
