L38_1 = 1
L39_1 = 0.4
L37_1[1] = L38_1
L37_1[2] = L39_1
L36_1.m_Bounce = L37_1
L37_1 = "그러니, 설령 그자가 저희의 발목을 잡는다 해도 제가 막을 테니 걱정하지 마옵소서."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ですから、彼に足を引っ張られた際は、わたくしが止めますのでご心配なされませんよう。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "So even if he tries to hold us back, rest assured because I'll stop him myself."
L36_1.m_Talk_ENG = L37_1
L37_1 = "所以即便他阻礙我們，我也會阻止他，請你不用擔心。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "So even if he tries to hold us back, rest assured because I'll stop him myself."
L36_1.m_Talk_DEU = L37_1
L37_1 = "So even if he tries to hold us back, rest assured because I'll stop him myself."
L36_1.m_Talk_FRA = L37_1
