L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "R"
L38_1.m_bCharPinup = true
L39_1 = "걱정하지 않아. 타기리온을 찾아 나보다 더 오랜 시간을 싸워온 건 당신이잖아?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "心配なんてしないよ。私よりも長い間、タギリオンを探して戦ってきたんだし。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I'm not worried. You're the one who has fought longer than I have to find Thagirion, after all."
L38_1.m_Talk_ENG = L39_1
L39_1 = "我不擔心。為了對抗塔基里翁，你比我奮戰更久吧？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "I'm not worried. You're the one who has fought longer than I have to find Thagirion, after all."
L38_1.m_Talk_DEU = L39_1
L39_1 = "I'm not worried. You're the one who has fought longer than I have to find Thagirion, after all."
L38_1.m_Talk_FRA = L39_1
