L40_1 = "EP15_ACT4_INTERLUDE19@165#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 239
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 726
L39_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "YOOMINA_FENRIR_NEXT_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "R"
L39_1.m_bCharPinup = true
L40_1 = "오히려 날 믿어줬으면 해. 당신의 염원이 헛되지 않도록, 나 역시 최선을 다할 테니까."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "むしろ、信じてほしいのは私のほうだよ。あなたの念願が無駄にならないように、こちらも全力を尽くすから。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Rather, I hope you'll trust me. I'll also do my best so that your wish will not be in vain."
L39_1.m_Talk_ENG = L40_1
L40_1 = "我反而希望你相信我。我也會竭盡全力，不讓你的願望白費。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "Rather, I hope you'll trust me. I'll also do my best so that your wish will not be in vain."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Rather, I hope you'll trust me. I'll also do my best so that your wish will not be in vain."
L39_1.m_Talk_FRA = L40_1
