L51_1 = "놀랍군. 한때 그루터기라 불릴 만큼 쇠락했던 나무가 다시 저토록 거대해지다니."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "驚いた。かつて切り株と呼ばれるほど衰えていた木が、再びあれほど巨大になるとは。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Remarkable. That tree, which had once withered enough to be called the Stump, has grown so massive again."
L50_1.m_Talk_ENG = L51_1
L51_1 = "真令人驚訝。曾衰敗到被稱為木墩的樹，如今竟然又變得如此巨大。"
