L2_1 = "Don't speak as if you are reminiscing about something you have seen before when you are seeing it for the first time. You're confusing me too."
L1_1.m_Talk_ENG = L2_1
L2_1 = "明明是第一次見到，不要像很瞭解它一樣發出感嘆，會讓人混亂啦。"
