L10_1 = "L_F_C"
L9_1.m_Pos = L10_1
L10_1 = "날개도 없이 그 짧은 다리로 여기까지 왔다는 게 꿈만 같긴 하네."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "翼もなしに、その短い脚でここまで来たなんて、確かに夢みたいかも。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "It almost feels like a dream that you made it all the way here with those short legs and no wings."
L9_1.m_Talk_ENG = L10_1
L10_1 = "沒有翅膀，靠這雙短腿走到這裡，還真像一場夢。"
