L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_DESPAIR"
L11_1 = "SERGEANT_GRONIA_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "R"
L11_1 = "말도 마세요. 그 먼 길에 괴물까지 발에 채여서 얼마나 힘들었는지..."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "考えたくもないです。道は長いし、化け物はうじゃうじゃして……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Don't even get me started. Monsters kept getting in my way along that long journey. It was exhausting..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "別說了。一路上還被怪物絆倒，真的很辛苦……"
L10_1.m_Talk_TWN = L11_1
L11_1 = "Don't even get me started. Monsters kept getting in my way along that long journey. It was exhausting..."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Don't even get me started. Monsters kept getting in my way along that long journey. It was exhausting..."
L10_1.m_Talk_FRA = L11_1
