L11_1.m_Face = L12_1
L11_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L11_1.m_Pos = "L"
L12_1 = "후후, 놀려도 눈치 못 채는 걸 보니 정말 힘들긴 했나 봐?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ふふ、冗談にも気づかないなんて、本当に大変だったみたいだね。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Haha, you're not even realizing I'm teasing you. It really must have been a tough trip."
L11_1.m_Talk_ENG = L12_1
L12_1 = "呵呵，看來真的很累，連被捉弄都沒發現。"
L11_1.m_Talk_TWN = L12_1
