L14_1 = "SERGEANT_GRONIA_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "R"
L14_1 = "아, 그러고보니 꼭대기에서 들린 그 연주 소리. 레아 씨가 지휘한 거죠?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "あ、そういえば頂上から聞こえたあの演奏。レアさんが指揮したんですよね？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Oh, right. That performance we heard from the top. You were the one who conducted it, Leah?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "對了，在山頂聽到的那段演奏，是蕾亞小姐指揮的吧？"
