L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 265
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 726
L15_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_SERIOUS"
L15_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L15_1.m_Pos = "C"
L15_1.m_bCharPinup = true
L15_1.m_bCharPinupEasingTime = 0.3
L16_1 = "나 혼자 한 게 아니야, 중사. 네퀴티아와 그 단원들의 도움을 받았거든."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "私一人でやったんじゃないよ、軍曹。ネキティアと団員たちの力を借りたから。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "It wasn't just me, Sergeant. I received help from Nequitia and the other members."
L15_1.m_Talk_ENG = L16_1
L16_1 = "不是我一個人完成的，莉奎蒂亞和團員們都有幫助我。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "It wasn't just me, Sergeant. I received help from Nequitia and the other members."
L15_1.m_Talk_DEU = L16_1
L16_1 = "It wasn't just me, Sergeant. I received help from Nequitia and the other members."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "EP15_ACT4_INTERLUDE19@185#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 266
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 726
L16_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_DESPAIR"
L16_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L16_1.m_Pos = "C"
L16_1.m_bCharPinup = true
L17_1 = "...속죄하겠다고 잘난 듯이 떠들어 놓고, 정작 나 자신은 무력한 탓에 멘탈 프린팅 같은 악에 의지하고 만 거야."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "……贖罪とか偉そうに言ったくせに、無力な私は結局メンタル・プリンティングという悪に頼ってしまったんだ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "...I talked big about wanting to atone, and yet I was powerless myself, so I ended up relying on something evil like Mental Printing."
L16_1.m_Talk_ENG = L17_1
L17_1 = "……嘴上說著要贖罪，結果卻因為我自身無力，只能仰賴像智力複印這樣的邪惡。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "...I talked big about wanting to atone, and yet I was powerless myself, so I ended up relying on something evil like Mental Printing."
L16_1.m_Talk_DEU = L17_1
L17_1 = "...I talked big about wanting to atone, and yet I was powerless myself, so I ended up relying on something evil like Mental Printing."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
