L19_1 = "EP15_ACT4_INTERLUDE19@187#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 268
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 726
L18_1.m_CutScenStrID = "EP15_ACT4_INTERLUDE19"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "SERGEANT_GRONIA_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L18_1.m_bCharPinup = true
L19_1 = "레아 씨가 네퀴티아의 존재를 부정하고 연주를 포기했다면, 멘탈 프린팅 기술은 끝내 수많은 희생양만 낳은 악인 채로 사라졌을 테니까요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "レアさんがネキティアの存在を否定して演奏を諦めていたら、メンタル・プリンティングはたくさんの犠牲者を生み出した悪の技術のままで終わっていたはずですから。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "If you had denied Nequitia's existence and given up on the performance, Mental Printing would have disappeared while remaining nothing more than an evil that only created countless sacrifices."
L18_1.m_Talk_ENG = L19_1
L19_1 = "如果蕾亞小姐否定莉奎蒂亞的存在並放棄演奏，智力複印技術最終只會成為只帶來無數犧牲的惡。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "If you had denied Nequitia's existence and given up on the performance, Mental Printing would have disappeared while remaining nothing more than an evil that only created countless sacrifices."
L18_1.m_Talk_DEU = L19_1
L19_1 = "If you had denied Nequitia's existence and given up on the performance, Mental Printing would have disappeared while remaining nothing more than an evil that only created countless sacrifices."
L18_1.m_Talk_FRA = L19_1
