L20_1.m_Pos = "C"
L20_1.m_bCharPinup = true
L21_1 = "하지만 안심해선 안돼. 아직 타기리온이라는 가장 중요한 화근이 남았으니까."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "でも油断したらダメだよ。まだタギリオンという一番の敵が残ってる。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "But we can't rest easy yet. The most critical source of trouble, Thagirion, still remains."
L20_1.m_Talk_ENG = L21_1
L21_1 = "但也不能鬆懈。因為塔基里翁這個最重要的禍根還在。"
