L24_1 = "EP15_ACT4_INTERLUDE19@192#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 273
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 726
