L24_1 = "BARTENDER_BAR_NULL_PR"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "L"
L23_1.m_bCharPinup = true
L24_1 = "아발론, 그루터기, 엘리시온, 타기리온, 요정과 악마 그리고 낙인..."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "アバロン、切り株、エリシオン、タギリオン、妖精と悪魔、そして烙印……"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Avalon, the Stump, Elysion, Thagirion, the fairies and the demons, and the mark..."
L23_1.m_Talk_ENG = L24_1
L24_1 = "阿瓦隆、木墩、艾利森、塔基里翁、精靈、惡魔，以及烙印……"
L23_1.m_Talk_TWN = L24_1
