L2_1 = "방금까진 좀 견딜 만 했는데... 미나 양이 무사한 걸 보니 긴장이 풀려서, 다시 아파요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "さっきまでは我慢できていたんですが……ミナさんの無事を確認したら緊張が解けて、痛みがぶり返しました。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I was managing somehow until just now... But seeing that you're safe, Mina, I finally relaxed, and it hurts again."
L1_1.m_Talk_ENG = L2_1
L2_1 = "剛才還撐得住……看到米娜小姐沒事，一放鬆就又開始痛了。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "I was managing somehow until just now... But seeing that you're safe, Mina, I finally relaxed, and it hurts again."
