L22_1.m_bCharPinup = true
L23_1 = "타기리온의 부하라면, 마왕의 기운이 보여야 할 텐데. 그런 게 전혀 안 느껴져요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "タギリオンの部下なら魔王の気配がするはずなのに、そういうのがまったくありません。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "If they were Thagirion's subordinates, I should be able to sense the Demon Lord's presence. But I don't feel anything like that at all."
L22_1.m_Talk_ENG = L23_1
L23_1 = "如果是塔基里翁的部下，應該能感受到魔王的氣息才對，但完全感覺不到。"
L22_1.m_Talk_TWN = L23_1
