L26_1 = "...낙원이 만들어지기 전부터, 이곳을 지키도록 설계된 인형이라고 들었어요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "……楽園が作られる前から、ここを守るように設計された人形だと聞きました。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "...I heard they are dolls designed to guard this place even before the Promised Land was created."
L25_1.m_Talk_ENG = L26_1
L26_1 = "……據說是從樂園尚未誕生之前，就被設計用來守護此地的人偶。"
